def parse_music(music_string: str) -> List[int]:
    music_string = music_string.replace(' ', '')
    result = []
    i = 0
    while i < len(music_string):
        if music_string[i] == 'o':
            if music_string[i + 1] == '|':
                result.append(2)
                i += 2
            else:
                result.append(4)
                i += 1
        else:
            result.append(1)
            i += 2
    return result

